39	export async function paymentMetadataHandler(_req: unknown, res: SsrRes): Promise<void> {
40	  try {
41	    const { app } = getConfig() as { app: SfPaymentsConfig };
42	    const response = await fetch(app.sfPayments.metadataUrl, {
43	      headers: { Accept: 'application/json' },
44	    });
45	    if (!response.ok) {
46	      throw new Error(`Metadata request failed with status: ${response.status}`);
47	    }
48	    const data = (await response.json()) as PaymentMethodData;
49	    const transformedData = transformIconPaths(data, new URL(app.sfPayments.metadataUrl).hostname);
50	    res.setHeader('Content-Type', 'application/json');
51	    res.json(transformedData);
52	  } catch (error) {
53	    res.status(500).json({
54	      error: 'Failed to fetch metadata',
55	      details: (error as Error).message,
56	    });
57	  }
58	}
